examples.code:
pipeline {
  agent any
  stages {
    stage("Hello") {
      steps { echo "Hello, club" }
    }
  }
}

pipeline {
  agent any
  stages {
    stage("Read") { steps { echo "Read source" } }
    stage("Check") { steps { echo "Check source" } }
  }
}

parameters {
  booleanParam(name: "RUN_CHECKS", defaultValue: true, description: "Run the practice checks")
}

stage("Optional check") {
  when { expression { params.RUN_CHECKS } }
  steps { echo "Run the chosen check" }
}

steps {
  timeout(time: 2, unit: "MINUTES") {
    echo "A bounded practice step"
  }
}

stage("Checks") {
  parallel {
    stage("Spelling") { steps { echo "Spelling check" } }
    stage("Links") { steps { echo "Link check" } }
  }
}
